import json
from datetime import datetime
def load(n):
    return [json.loads(l) for l in open(n) if l.strip()]
def ts(d):
    t=d.get('timestamp')
    return datetime.fromisoformat(t.replace('Z','+00:00')) if t else None

import sys
name=sys.argv[1]
ents=load(name)
prev=None
for i,e in enumerate(ents):
    t=ts(e); gap=(t-prev).total_seconds() if (t and prev) else 0
    if t: prev=t
    typ=e.get('type')
    m=e.get('message') or {}
    desc=''
    if typ=='assistant':
        c=m.get('content') or []
        bits=[]
        for b in c:
            if not isinstance(b,dict): continue
            if b.get('type')=='text': bits.append('TEXT:'+b['text'][:220].replace('\n',' '))
            elif b.get('type')=='tool_use':
                inp=b.get('input',{})
                s=inp.get('command') or inp.get('file_path') or inp.get('pattern') or inp.get('description') or inp.get('prompt') or ''
                bits.append(f"TOOL {b.get('name')}: {str(s)[:160]}".replace('\n',' '))
            elif b.get('type')=='thinking': bits.append('THINK('+str(len(b.get('thinking','')))+')')
        u=m.get('usage') or {}
        desc=' || '.join(bits)+f"  [in={u.get('input_tokens')} out={u.get('output_tokens')} cr={u.get('cache_read_input_tokens')}]"
    elif typ=='user':
        c=m.get('content')
        if isinstance(c,list):
            for b in c:
                if isinstance(b,dict) and b.get('type')=='tool_result':
                    r=b.get('content')
                    txt=r if isinstance(r,str) else ' '.join(x.get('text','') for x in r if isinstance(x,dict))
                    desc='RESULT'+('[ERR]' if b.get('is_error') else '')+': '+txt[:200].replace('\n',' ')
                elif isinstance(b,dict) and b.get('type')=='text':
                    desc='USERTEXT: '+b['text'][:200].replace('\n',' ')
        elif isinstance(c,str): desc='USERTEXT: '+c[:200].replace('\n',' ')
    elif typ=='system':
        desc='SYS('+str(e.get('subtype'))+'): '+str(e.get('content'))[:180].replace('\n',' ')
    else:
        desc=typ+' '+str(e.get('subtype') or '')[:80]
    mark='  <<<GAP' if gap>=60 else ''
    print(f"[{i:3}] +{gap:7.1f}s {typ:10} {desc[:300]}{mark}")
EOF
