import json
from datetime import datetime
def load(n): return [json.loads(l) for l in open(n) if l.strip()]
def ts(d):
    t=d.get('timestamp'); return datetime.fromisoformat(t.replace('Z','+00:00')) if t else None

for name in ['log92.jsonl','log98.jsonl']:
    ents=load(name)
    # map tool_use id -> (name, input, time); find matching tool_result time
    starts={}
    for i,e in enumerate(ents):
        if e.get('type')=='assistant':
            for b in (e.get('message') or {}).get('content') or []:
                if isinstance(b,dict) and b.get('type')=='tool_use':
                    starts[b['id']]=(b['name'], json.dumps(b.get('input'))[:110], ts(e), i)
    durs=[]
    for i,e in enumerate(ents):
        if e.get('type')=='user':
            c=(e.get('message') or {}).get('content')
            if isinstance(c,list):
                for b in c:
                    if isinstance(b,dict) and b.get('type')=='tool_result' and b.get('tool_use_id') in starts:
                        n,inp,t0,i0=starts[b['tool_use_id']]
                        t1=ts(e)
                        if t0 and t1: durs.append(((t1-t0).total_seconds(), n, inp, i0, i))
    durs.sort(reverse=True)
    tall=[ts(e) for e in ents if ts(e)]
    span=(tall[-1]-tall[0]).total_seconds()
    # human idle: gaps > 300s
    idle=0; gaps=[]
    for a,b in zip(tall,tall[1:]):
        g=(b-a).total_seconds()
        if g>300: idle+=g; gaps.append(g)
    tool_total=sum(d[0] for d in durs)
    print('='*60); print(name)
    print(f'  wall span        : {span:9.1f}s ({span/60:.1f} min)')
    print(f'  human-idle gaps  : {idle:9.1f}s  {[round(g) for g in gaps]}')
    print(f'  agent-active     : {span-idle:9.1f}s ({(span-idle)/60:.1f} min)')
    print(f'  sum tool latency : {tool_total:9.1f}s over {len(durs)} calls')
    print('  --- slowest 10 tool calls ---')
    for d in durs[:10]:
        print(f'   {d[0]:8.1f}s  #{d[3]}->{d[4]}  {d[1]}: {d[2]}')
EOF
